:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #172b35;
  color: #f5f3e9;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #172b35;
  background-image: radial-gradient(ellipse at 50% 0%, #27434b 0, transparent 65%);
}
button { font: inherit; }
.meter {
  width: min(100%, 440px);
  padding: 34px;
  border: 1px solid #3a5456;
  border-radius: 24px;
  background: #20363d;
  box-shadow: 0 24px 70px #0b171c88;
}
.meter-header { text-align: center; }
.taxi-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin: 0 auto 16px;
  border-radius: 15px;
  background: #f4c95d;
  color: #20363d;
  font-size: 25px;
}
.eyebrow, .fare-label {
  margin: 0;
  color: #9bb1ac;
  font-size: 0.75rem;
  font-weight: 750;
  letter-spacing: 0.16em;
}
h1 { margin: 8px 0 4px; font-size: clamp(1.7rem, 7vw, 2rem); letter-spacing: -0.04em; }
.subtitle { margin: 0; color: #b6c6bd; }
.fare-panel {
  margin-top: 28px;
  padding: 22px 16px 18px;
  border: 1px solid #56665a;
  border-radius: 17px;
  background: #2a4145;
  text-align: center;
}
.fare-label { color: #c6c9a9; }
.fare { margin: 4px 0 0; color: #f4c95d; font-size: clamp(3rem, 14vw, 4rem); font-weight: 800; line-height: 1.15; letter-spacing: -0.06em; font-variant-numeric: tabular-nums; }
.currency { margin-right: 3px; font-size: 0.55em; vertical-align: 0.18em; }
.fare-note { margin: 5px 0 0; color: #b6c6bd; font-size: 0.875rem; }
.trip-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 16px; }
.stat { display: grid; grid-template-columns: 26px 1fr; align-items: center; padding: 15px; border: 1px solid #3a5456; border-radius: 14px; background: #1a3037; }
.stat-icon { grid-row: span 2; color: #f4c95d; font-size: 1.2rem; }
.stat-label { color: #b6c6bd; font-size: 0.875rem; }
.stat-value { font-size: 1.25rem; font-weight: 750; font-variant-numeric: tabular-nums; }
.stat-value small { color: #b6c6bd; font-size: 0.75rem; font-weight: 500; }
.controls { display: grid; gap: 10px; margin-top: 20px; }
.action-button, .reset-button { min-height: 54px; border-radius: 13px; cursor: pointer; transition: background-color 140ms ease, transform 140ms ease, border-color 140ms ease; }
.action-button { display: flex; align-items: center; justify-content: center; gap: 9px; border: 1px solid #f4c95d; background: #f4c95d; color: #20363d; font-weight: 750; }
.action-button:hover { border-color: #ffdc82; background: #ffdc82; }
.button-symbol { font-size: 1.25rem; line-height: 1; }
.reset-button { width: 100%; margin-top: 10px; border: 1px solid #587071; background: transparent; color: #e0e8de; font-weight: 650; }
.reset-button:hover { border-color: #a4bcb3; background: #29434a; }
button:focus-visible { outline: 3px solid #f5f3e9; outline-offset: 3px; }
button:active { transform: translateY(2px) scale(0.99); }
footer { display: flex; flex-wrap: wrap; justify-content: center; gap: 5px 14px; margin-top: 23px; color: #9bb1ac; font-size: 0.75rem; letter-spacing: 0.04em; }
footer span { color: #c6d1c9; letter-spacing: 0; }
@media (max-width: 390px) { .meter { padding: 25px 19px; } .stat { padding: 12px 10px; } }

const distanceDisplay = document.getElementById('distance');
const waitingDisplay = document.getElementById('waiting');
const fareDisplay = document.getElementById('fare');

let distanceKm = 0;
let waitingMinutes = 0;

function updateMeter() {
  distanceDisplay.textContent = distanceKm;
  waitingDisplay.textContent = waitingMinutes;
  const fare = 3 + distanceKm * 1.5 + waitingMinutes * 0.4;
  fareDisplay.textContent = fare.toFixed(2);
}

document.getElementById('add-km').addEventListener('click', () => {
  distanceKm += 1;
  updateMeter();
});

document.getElementById('add-minute').addEventListener('click', () => {
  waitingMinutes += 1;
  updateMeter();
});

document.getElementById('new-trip').addEventListener('click', () => {
  distanceKm = 0;
  waitingMinutes = 0;
  updateMeter();
});
